        static std::size_t child(T* data, std::size_t count, std::size_t hole) {
            const auto cmp = typename Queue::value_compare{};
            const auto first = hole * 4 + 1;
            auto best = first;
            T value = data[first];
            const auto remaining = count - first;
            if (remaining > 1 && cmp(value, data[first + 1])) {
                best = first + 1;
                value = data[first + 1];
            }
            if (remaining > 2 && cmp(value, data[first + 2])) {
                best = first + 2;
                value = data[first + 2];
            }
            if (remaining > 3 && cmp(value, data[first + 3])) best = first + 3;
            return best;
