                const auto best = child(data, count, hole);
                data[hole] = data[best];
                hole = best;
            }
            while (hole != root) {
                const auto parent = (hole - 1) / 4;
                if (!cmp(data[parent], value)) break;
                data[hole] = data[parent];
                hole = parent;
