    void pop_pair()
#if defined(__GNUC__) && !defined(__clang__)
        requires (!four_way)
#endif
    {
        if constexpr (std::is_integral_v<T> && !std::is_same_v<T, bool>) {
            auto& a = values_.storage();
            auto& b = erased_.storage();
            const T last_a = a.back(), last_b = b.back();
