            }
        }
#else
        using Queue::Queue;
#endif
    };
    using Storage = std::conditional_t<std::is_integral_v<T> && !std::is_same_v<T, bool>,
        Heap, Queue>;
    Storage values_, erased_;

#if defined(__GNUC__) && !defined(__clang__)
