                const auto first = hole * 4 + 1;
                const auto last = (count - 2) / 4;
                if (first <= last) __builtin_prefetch(data + first * 4 + 1);
                if (first + 1 <= last) __builtin_prefetch(data + (first + 1) * 4 + 1);
