            if constexpr (four_way) {
                auto& values = this->c;
                const T value = values.back();
                values.pop_back();
                if (!values.empty()) restore(values.data(), values.size(), 0, value);

            } else {
                auto& values = this->c;
                if (values.size() == 1) {
                    values.pop_back();
                    return;
                }
                const T value = values.back();
                values.pop_back();
                auto* const data = values.data();
                const auto count = values.size();
