                const auto cmp = typename Queue::value_compare{};
                while (hole < count / 2) {
                    auto child = hole * 2 + 1;
                    if (child + 1 < count && cmp(data[child], data[child + 1])) ++child;
                    data[hole] = data[child];
                    hole = child;
                }
