        Queue{}.swap(erased_);
    }

private:
#if defined(__GNUC__) && !defined(__clang__)
    static constexpr bool four_way = std::is_integral_v<T> &&
        (std::numeric_limits<T>::digits == 63 || std::numeric_limits<T>::digits == 64);
