#include HEADER
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <numeric>
#include <random>
#include <vector>
using I=std::int64_t;using U=std::uint64_t;using Clock=std::chrono::steady_clock;
template<bool M>[[gnu::noipa]]I observe(ErasablePriorityQueue<I,M>&q){return q.top();}
template<bool M>void run(int n,int kind,int mode){
 std::vector<I>a(n);std::iota(a.begin(),a.end(),-n/2);if(kind)for(int i=0;i<n;++i)a[i]=i%8;std::mt19937 g(814191);std::shuffle(a.begin(),a.end(),g);
 double elapsed=0;U sum=0;const int reps=n==32?200:2;
 for(int rep=0;rep<reps;++rep){
  ErasablePriorityQueue<I,M>q;if(mode!=0)q=ErasablePriorityQueue<I,M>(a);
  if(mode==3){for(I x:a)q.erase(x);q.push(M?INT64_MAX:INT64_MIN);}
  const auto begin=Clock::now();
  if(mode==0)for(I x:a)q.push(x);
  if(mode==1)while(!q.empty()){sum+=U(q.top());q.pop();}
  if(mode==2)for(int i=0;i<n;++i){q.push(a[i]+n);sum+=U(q.top());q.pop();}
  if(mode==3)sum+=U(q.top());
  if(mode==4)for(int i=0;i<n/2;++i)q.erase(a[i]);
  if(mode==5)for(int i=0;i<100000;++i)sum+=U(observe(q));
  const auto end=Clock::now();elapsed+=std::chrono::duration<double,std::nano>(end-begin).count();
  while(auto x=q.extract_top())sum+=U(*x);
 }
 std::printf("%d %d %d %d %.9g %ju\n",n,int(M),kind,mode,elapsed/reps,std::uintmax_t(sum));
}
int main(){for(int n:{32,100000,1000000})for(int k:{0,1})for(int m=0;m<6;++m){run<true>(n,k,m);run<false>(n,k,m);}}

